public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Edits the media content of a message, including message caption. If only the caption needs to be edited, use editMessageCaption instead.
    /// The type of message content in an album can't be changed with exception of replacing a photo with a video or vice versa. Returns the edited message after the edit is completed on the server side
    /// </summary>
    public Task<TdLib.TdApi.Objects.Message> EditMessageMediaAsync(long chatId = default, long messageId = default, ReplyMarkup replyMarkup = default, InputMessageContent inputMessageContent = default)
    {

           using var activity =  StartCallActivity("EditMessageMediaAsync", typeof(EditMessageMedia).FullName ?? "EditMessageMediaAsync");

           try
           {
             return client.EditMessageMediaAsync(chatId, messageId, replyMarkup, inputMessageContent);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
